package com.chenyehui.bible.data

import android.content.Context
import android.util.LruCache
import org.json.JSONArray
import org.json.JSONObject

/**
 * Reads the JSON assets generated by tools/build_bible.py.
 *
 * Only the book currently open is parsed; an LRU cache keeps a handful of
 * books around while moving between chapters and translations.
 */
class BibleRepository(private val context: Context) {

    val manifest: Manifest by lazy {
        val text = context.assets.open("bible/manifest.json")
            .bufferedReader(Charsets.UTF_8)
            .use { it.readText() }
        parseManifest(JSONObject(text))
    }

    private val bookCache = object : LruCache<String, Book>(8) {}

    @Synchronized
    fun book(versionId: String, bookId: Int): Book {
        val key = "$versionId/$bookId"
        bookCache.get(key)?.let { return it }
        val path = "bible/$versionId/$bookId.json"
        val text = context.assets.open(path)
            .bufferedReader(Charsets.UTF_8)
            .use { it.readText() }
        val book = parseBook(
            root = JSONObject(text),
            stripPinyin = versionId == "muling" || versionId == "sigao",
        )
        bookCache.put(key, book)
        return book
    }

    private fun parseManifest(root: JSONObject): Manifest {
        val versionsArray = root.getJSONArray("versions")
        val versions = ArrayList<TranslationInfo>(versionsArray.length())
        for (i in 0 until versionsArray.length()) {
            val obj = versionsArray.getJSONObject(i)
            val booksArray = obj.getJSONArray("books")
            val books = ArrayList<BookMeta>(booksArray.length())
            for (j in 0 until booksArray.length()) {
                val b = booksArray.getJSONObject(j)
                books += BookMeta(
                    id = b.getInt("id"),
                    title = b.getString("title"),
                    short = b.getString("short"),
                    testament = b.getInt("testament"),
                    chapters = b.getInt("chapters"),
                )
            }
            versions += TranslationInfo(
                id = obj.getString("id"),
                title = obj.getString("title"),
                short = obj.getString("short"),
                language = obj.getString("language"),
                books = books,
            )
        }
        return Manifest(versions)
    }

    private fun parseBook(root: JSONObject, stripPinyin: Boolean): Book {
        fun content(value: String): String =
            if (stripPinyin) stripPinyinAnnotations(value) else value

        val chaptersArray = root.getJSONArray("chapters")
        val chapters = ArrayList<Chapter>(chaptersArray.length())
        for (i in 0 until chaptersArray.length()) {
            val chapterObj = chaptersArray.getJSONObject(i)
            val blocksArray = chapterObj.getJSONArray("b")
            val blocks = ArrayList<Block>(blocksArray.length())
            for (j in 0 until blocksArray.length()) {
                val block = blocksArray.getJSONArray(j)
                when (block.getString(0)) {
                    "v" -> blocks += Block.Verse(
                        number = block.getInt(1),
                        text = content(block.getString(2)),
                    )

                    "h3" -> blocks += Block.Heading(3, content(block.getString(1)))
                    "h4" -> blocks += Block.Heading(4, content(block.getString(1)))
                    "br" -> blocks += Block.ParagraphBreak
                    else -> error("Unknown block type: ${block.getString(0)}")
                }
            }
            chapters += Chapter(chapterObj.getInt("n"), blocks)
        }
        return Book(
            id = root.getInt("id"),
            title = root.getString("title"),
            chapters = chapters,
        )
    }
}
